// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.benchmark;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

import org.eclipse.rdf4j.query.QueryEvaluationException;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailTupleQuery;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeDecisionTestAccess;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeDecisionTestAccess.Captured;

/**
 * The measurement loop shared by the regret harnesses: preview a query's decisions with every admitted candidate's
 * priced features, force each admitted strategy and time it, and render the timings as the TSV
 * {@code scripts/lmdb-regret-report.py} and {@code scripts/lmdb-fit-prior.py} read. Two protocols: the warmed median of
 * a fixed number of runs per strategy (the FOAF harness), and the interleaved form for large stores (the theme mode):
 * the strategies of the top decision run interleaved, execution by execution, for a warm-up window, then exactly
 * {@code rounds} times each, still interleaved, and the fastest run counts.
 */
final class LmdbNativeRegretHarness {

	/** One strategy's measurement at one decision of one query on one store. */
	record Timing(String query, String indexes, String adjacency, String point, String id, boolean chosen,
			boolean admitted, double medianNanos, double minNanos, long rows, double expectedNanos, double lowNanos,
			double highNanos, double[] features, String note) {
	}

	record Measurement(double medianNanos, double minNanos, long rows, String note) {
		static final Measurement NONE = new Measurement(Double.NaN, Double.NaN, -1L, "");
	}

	private LmdbNativeRegretHarness() {
	}

	/** The selector's decisions for {@code query}, by decision point, with every candidate's quote. */
	static Map<String, List<Captured>> preview(SailRepository repository, String query) throws Exception {
		List<Captured> captured = new ArrayList<>();
		try (AutoCloseable ignored = LmdbNativeDecisionTestAccess.capture(captured);
				SailRepositoryConnection connection = repository.getConnection()) {
			connection.prepareTupleQuery(query).explain(Explanation.Level.Optimized);
		}
		Map<String, List<Captured>> byPoint = new LinkedHashMap<>();
		for (Captured entry : captured) {
			byPoint.computeIfAbsent(entry.decisionPoint(), key -> new ArrayList<>()).add(entry);
		}
		return byPoint;
	}

	/** Every admitted strategy at every decision point, each timed as the warmed median of fixed runs. */
	static List<Timing> measureQuery(SailRepository repository, String queryId, String indexes, String adjacency,
			String query, int warmups, int measurements) throws Exception {
		Map<String, List<Captured>> byPoint = preview(repository, query);
		List<Timing> timings = new ArrayList<>();
		Measurement unforced = measureMedian(repository, query, null, warmups, measurements, 0);
		for (Map.Entry<String, List<Captured>> point : byPoint.entrySet()) {
			Set<String> admitted = admitted(point.getValue());
			String winner = winner(point.getValue());
			for (String id : admitted) {
				boolean chosen = id.equals(winner);
				Measurement measurement = chosen ? unforced
						: measureMedian(repository, query, id, warmups, measurements, 0);
				timings.add(timing(queryId, indexes, adjacency, point.getKey(), id, chosen, point.getValue(),
						measurement));
			}
		}
		return timings;
	}

	/**
	 * The theme protocol: every admitted strategy of the first decision point, interleaved execution by execution for
	 * {@code windowNanos}, then exactly {@code rounds} runs each, still interleaved; the fastest run of each counts
	 * (recorded as both the median and the minimum column). A run is capped at {@code timeoutSeconds}.
	 */
	static List<Timing> measureQueryInterleaved(SailRepository repository, String queryId, String indexes,
			String adjacency, String query, long windowNanos, int rounds, int timeoutSeconds) throws Exception {
		Map<String, List<Captured>> byPoint = preview(repository, query);
		List<Timing> timings = new ArrayList<>();
		if (byPoint.isEmpty()) {
			return timings;
		}
		Map.Entry<String, List<Captured>> point = byPoint.entrySet().iterator().next();
		List<String> admitted = new ArrayList<>(admitted(point.getValue()));
		String winner = winner(point.getValue());
		if (winner != null && !admitted.contains(winner)) {
			admitted.add(winner);
		}
		Map<String, String> notes = new LinkedHashMap<>();
		long warmStart = System.nanoTime();
		int warmRuns = 0;
		while (System.nanoTime() - warmStart < windowNanos) {
			for (String id : admitted) {
				try {
					execute(repository, query, id.equals(winner) ? null : id, timeoutSeconds);
				} catch (QueryEvaluationException e) {
					notes.put(id, "failed: " + firstLine(e.getMessage()));
				}
				warmRuns++;
			}
		}
		Map<String, double[]> samples = new LinkedHashMap<>();
		Map<String, Long> rows = new LinkedHashMap<>();
		for (int run = 0; run < rounds; run++) {
			for (String id : admitted) {
				double[] times = samples.computeIfAbsent(id, key -> new double[rounds]);
				try {
					long[] counted = new long[1];
					times[run] = execute(repository, query, id.equals(winner) ? null : id, timeoutSeconds, counted);
					rows.put(id, counted[0]);
				} catch (QueryEvaluationException e) {
					times[run] = Double.NaN;
					notes.put(id, "failed: " + firstLine(e.getMessage()));
				}
			}
		}
		for (String id : admitted) {
			double[] times = samples.get(id);
			double fastest = Arrays.stream(times).filter(t -> !Double.isNaN(t)).min().orElse(Double.NaN);
			String note = "fastest-of-" + rounds + " after " + warmRuns + " interleaved warm-up runs"
					+ (notes.containsKey(id) ? "; " + notes.get(id) : "");
			timings.add(timing(queryId, indexes, adjacency, point.getKey(), id, id.equals(winner),
					point.getValue(), new Measurement(fastest, fastest, rows.getOrDefault(id, -1L), note)));
		}
		return timings;
	}

	private static Set<String> admitted(List<Captured> point) {
		Set<String> admitted = new LinkedHashSet<>();
		for (Captured entry : point) {
			if (entry.admitted()) {
				admitted.add(baseId(entry.id()));
			}
		}
		return admitted;
	}

	private static String winner(List<Captured> point) {
		for (Captured entry : point) {
			if (entry.winner()) {
				return baseId(entry.id());
			}
		}
		return null;
	}

	private static Timing timing(String queryId, String indexes, String adjacency, String point, String id,
			boolean chosen, List<Captured> entries, Measurement measurement) {
		Captured quote = entries.stream()
				.filter(entry -> entry.admitted() && baseId(entry.id()).equals(id))
				.findFirst()
				.orElse(null);
		return new Timing(queryId, indexes, adjacency, point, id, chosen, true, measurement.medianNanos,
				measurement.minNanos, measurement.rows, quote == null ? Double.NaN : quote.expectedNanos(),
				quote == null ? Double.NaN : quote.lowNanos(), quote == null ? Double.NaN : quote.highNanos(),
				quote == null ? null : quote.expectedFeatures(), measurement.note);
	}

	/** The warmed median of {@code measurements} runs ({@code timeoutSeconds} 0 for no cap). */
	static Measurement measureMedian(SailRepository repository, String query, String forced, int warmups,
			int measurements, int timeoutSeconds) {
		double[] samples = new double[measurements];
		long rows = -1L;
		try {
			for (int i = 0; i < warmups + measurements; i++) {
				long[] counted = new long[1];
				double elapsed = execute(repository, query, forced, timeoutSeconds, counted);
				rows = counted[0];
				if (i >= warmups) {
					samples[i - warmups] = elapsed;
				}
			}
		} catch (QueryEvaluationException e) {
			return new Measurement(Double.NaN, Double.NaN, -1L, "declined: " + firstLine(e.getMessage()));
		}
		Arrays.sort(samples);
		return new Measurement(samples[samples.length / 2], samples[0], rows, "");
	}

	static double execute(SailRepository repository, String query, String forced, int timeoutSeconds) {
		return execute(repository, query, forced, timeoutSeconds, new long[1]);
	}

	/** One execution, fully drained; its wall time in nanoseconds, the row count in {@code counted[0]}. */
	static double execute(SailRepository repository, String query, String forced, int timeoutSeconds,
			long[] counted) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
			if (timeoutSeconds > 0) {
				prepared.setMaxExecutionTime(timeoutSeconds);
			}
			if (forced != null) {
				prepared.setForcedLmdbExecutionStrategy(forced);
			}
			long started = System.nanoTime();
			long count = 0L;
			try (TupleQueryResult result = prepared.evaluate()) {
				while (result.hasNext()) {
					result.next();
					count++;
				}
			}
			counted[0] = count;
			return System.nanoTime() - started;
		}
	}

	static String firstLine(String message) {
		if (message == null) {
			return "";
		}
		int end = message.indexOf('\n');
		return (end < 0 ? message : message.substring(0, end)).replace('\t', ' ');
	}

	static String baseId(String id) {
		int paren = id.indexOf('(');
		return paren > 0 ? id.substring(0, paren) : id;
	}

	static List<String> render(List<Timing> timings) {
		List<String> lines = new ArrayList<>();
		lines.add("# query\tindexes\tadjacency\tpoint\tstrategy\tchosen\tmedianNanos\tminNanos\trows\texpectedNanos"
				+ "\tlowNanos\thighNanos\tnote\tfeatures("
				+ String.join(",", LmdbNativeDecisionTestAccess.featureNames())
				+ ")");
		for (Timing timing : timings) {
			StringBuilder features = new StringBuilder();
			if (timing.features != null) {
				for (int i = 0; i < timing.features.length; i++) {
					if (i > 0) {
						features.append(',');
					}
					features.append(String.format(Locale.ROOT, "%.3f", timing.features[i]));
				}
			}
			lines.add(String.join("\t", timing.query, timing.indexes, timing.adjacency, timing.point, timing.id,
					timing.chosen ? "chosen" : "-", number(timing.medianNanos), number(timing.minNanos),
					Long.toString(timing.rows), number(timing.expectedNanos), number(timing.lowNanos),
					number(timing.highNanos), timing.note, features.toString()));
		}
		return lines;
	}

	static String number(double value) {
		return Double.isNaN(value) ? "NaN" : String.format(Locale.ROOT, "%.0f", value);
	}

	/** Per decision: the chosen strategy's time over the fastest measured time (1.0 is a perfect choice). */
	static List<Regret> regrets(List<Timing> timings) {
		Map<String, List<Timing>> decisions = new LinkedHashMap<>();
		for (Timing timing : timings) {
			decisions.computeIfAbsent(timing.query + "\t" + timing.indexes + "\t" + timing.adjacency + "\t"
					+ timing.point, key -> new ArrayList<>()).add(timing);
		}
		List<Regret> regrets = new ArrayList<>();
		for (Map.Entry<String, List<Timing>> decision : decisions.entrySet()) {
			Timing chosen = null;
			Timing fastest = null;
			for (Timing timing : decision.getValue()) {
				if (Double.isNaN(timing.medianNanos)) {
					continue;
				}
				if (timing.chosen) {
					chosen = timing;
				}
				if (fastest == null || timing.medianNanos < fastest.medianNanos) {
					fastest = timing;
				}
			}
			if (chosen != null && fastest != null) {
				regrets.add(new Regret(decision.getKey(), chosen, fastest, chosen.medianNanos / fastest.medianNanos));
			}
		}
		return regrets;
	}

	record Regret(String decision, Timing chosen, Timing fastest, double ratio) {
	}

	static String summary(List<Timing> timings) {
		StringBuilder out = new StringBuilder("\nstrategy regret (chosen / fastest)\n");
		double worst = 1D;
		int decided = 0;
		int optimal = 0;
		for (Regret regret : regrets(timings)) {
			decided++;
			if (regret.ratio <= 1.05D) {
				optimal++;
			}
			worst = Math.max(worst, regret.ratio);
			out.append(String.format(Locale.ROOT, "%-80s chosen=%-28s %8.2f ms  fastest=%-28s %8.2f ms  regret=%.2f%n",
					regret.decision.replace('\t', ' '), regret.chosen.id, regret.chosen.medianNanos / 1e6,
					regret.fastest.id, regret.fastest.medianNanos / 1e6, regret.ratio));
		}
		out.append(String.format(Locale.ROOT, "decisions=%d optimalWithin5pct=%d worstRegret=%.2f%n", decided, optimal,
				worst));
		return out.toString();
	}
}
